#!/usr/bin/env node
// Copies the shared sources the CLI needs into src/vendor/ so the published package has
// no dependency on the workspace. Generated output is git-ignored and never committed.
import { existsSync, mkdirSync, readdirSync, readFileSync, rmSync, writeFileSync } from 'node:fs';
import { dirname, join, resolve } from 'node:path';
import { fileURLToPath, pathToFileURL } from 'node:url';

/** Directories under packages/shared/src/utilities that the CLI vendors. */
export const VENDORED_DIRS = ['quarterly-markdown', 'cli-contract'];

const BANNER =
  '// GENERATED by packages/cli/scripts/vendor-shared.mjs from packages/shared — do not edit.\n';

/** Adds `.js` to relative module specifiers (`from './x'`, `import './x'`) for NodeNext. */
export function rewriteSpecifiers(source) {
  return source.replace(
    /(\bfrom\s+|\bimport\s+)(['"])(\.{1,2}\/[^'"]+)\2/g,
    (match, lead, quote, specifier) =>
      specifier.endsWith('.js') ? match : `${lead}${quote}${specifier}.js${quote}`
  );
}

function isSourceFile(name) {
  return name.endsWith('.ts') && !name.endsWith('.test.ts');
}

function listSourceFiles(dir) {
  return readdirSync(dir, { withFileTypes: true })
    .filter((entry) => entry.name !== '__fixtures__')
    .flatMap((entry) => {
      if (entry.isDirectory()) {
        return listSourceFiles(join(dir, entry.name)).map((file) => join(entry.name, file));
      }
      return isSourceFile(entry.name) ? [entry.name] : [];
    })
    .sort();
}

/** Throws when a relative import in `source` does not resolve to a sibling `.ts` file. */
function assertResolvable(sourceFile, source) {
  for (const match of source.matchAll(/(?:\bfrom\s+|\bimport\s+)['"](\.{1,2}\/[^'"]+)['"]/g)) {
    const specifier = match[1].endsWith('.js') ? match[1].slice(0, -3) : match[1];
    if (!existsSync(resolve(dirname(sourceFile), `${specifier}.ts`))) {
      throw new Error(
        `vendor-shared: ${sourceFile} imports "${match[1]}", which is not a .ts file`
      );
    }
  }
}

/** Replaces `destRoot` with rewritten copies of every vendored directory under `srcRoot`. */
export function vendorShared(srcRoot, destRoot) {
  rmSync(destRoot, { recursive: true, force: true });
  for (const name of VENDORED_DIRS) {
    const srcDir = join(srcRoot, name);
    for (const file of listSourceFiles(srcDir)) {
      const sourceFile = join(srcDir, file);
      const source = readFileSync(sourceFile, 'utf8');
      assertResolvable(sourceFile, source);
      const target = join(destRoot, name, file);
      mkdirSync(dirname(target), { recursive: true });
      writeFileSync(target, BANNER + rewriteSpecifiers(source));
    }
  }
}

const entry = process.argv[1];
if (entry && import.meta.url === pathToFileURL(entry).href) {
  const here = dirname(fileURLToPath(import.meta.url));
  const [srcArg, destArg] = process.argv.slice(2);
  vendorShared(
    srcArg ?? join(here, '..', '..', 'shared', 'src', 'utilities'),
    destArg ?? join(here, '..', 'src', 'vendor')
  );
}
